function renderChart(points){const container=$('#chart');container.replaceChildren();if(!points.length){container.append(el('p','hint',state.mode==='rent'?'가격을 계산할 수 있는 거래가 없습니다. 기준 보증금·전환율·조회 조건을 확인하세요.':'날짜가 확인되는 거래가 없어 그래프를 그릴 수 없습니다.'));return;}const NS='http://www.w3.org/2000/svg',svg=document.createElementNS(NS,'svg');svg.setAttribute('viewBox','0 0 1100 250');svg.setAttribute('role','img');svg.setAttribute('aria-label',(state.mode==='rent'?rentalMetricLabel():'기간별 평균 평당가')+' 그래프. 각 점을 선택하면 가격과 거래 건수가 표시됩니다.');const make=(tag,attrs,text)=>{const n=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);if(text!=null)n.textContent=text;svg.append(n);return n;};const values=points.map(p=>p.average);let lo=Math.min(...values),hi=Math.max(...values);const pad=Math.max((hi-lo)*.18,1);lo=Math.max(0,lo-pad);hi+=pad;const range=E.sourceDateRange(state.source,state.raw);const date=p=>Date.parse(p.date+(p.date.length===7?'-01':'')+'T00:00:00Z'),min=Date.parse(range.from+'T00:00:00Z'),end=Date.parse(range.to+'T00:00:00Z'),span=Math.max(1,end-min);const xy=p=>[85+(Math.max(min,Math.min(end,date(p)))-min)/span*965,205-(p.average-lo)/(hi-lo)*180];for(let i=0;i<4;i++){const y=25+i*60;make('line',{x1:85,x2:1050,y1:y,y2:y,class:'chart-grid'});make('text',{x:73,y:y+5,'text-anchor':'end',class:'chart-label'},nf.format(hi-(hi-lo)*i/3));}make('polyline',{points:E.stepCoordinates(points,range.from,range.to).map(([x,value])=>[85+(x-min)/span*965,205-(value-lo)/(hi-lo)*180].join(',')).join(' '),class:'chart-line'});for(const ratio of [0,.5,1]){make('text',{x:85+ratio*965,y:234,'text-anchor':'middle',class:'chart-label'},new Date(min+ratio*span).toISOString().slice(0,10));}for(const p of points){const[x,y]=xy(p),text=`${p.date}\n${state.mode==='rent'?rentalMetricLabel():'평균 평당가'}: ${state.mode==='rent'?new Intl.NumberFormat('ko-KR',{maximumFractionDigits:2}).format(p.average):nf.format(p.average)} ${state.mode==='rent'?(state.filters.lease==='월세'?'만 원/월':'만 원'):'만원/평'}\n거래 건수: ${p.count}건`;const dot=make('circle',{cx:x,cy:y,r:5,class:'chart-point',tabindex:0,'aria-label':text});const title=document.createElementNS(NS,'title');title.textContent=text;dot.append(title);const show=e=>{const tip=$('#chartTooltip');tip.textContent=text;tip.hidden=false;const rect=dot.getBoundingClientRect(),mx=e.clientX??rect.x,my=e.clientY??rect.y;tip.style.left=Math.max(8,Math.min(innerWidth-260,mx+14))+'px';tip.style.top=Math.max(8,my-88)+'px';};dot.addEventListener('pointerenter',show);dot.addEventListener('pointermove',show);dot.addEventListener('focus',show);dot.addEventListener('pointerleave',()=>$('#chartTooltip').hidden=true);dot.addEventListener('blur',()=>$('#chartTooltip').hidden=true);}container.append(svg,el('p','chart-description','가로축: 원본 전체 조회기간 ' +range.from+' ~ '+range.to+' · 계단의 수평선은 직전 관측 평균을 이어 표시한 참고선입니다. 거래가 없는 기간의 실제 가격을 뜻하지 않습니다.'));}
const escapeHTML=s=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const tsv=v=>{let s=String(v??'');if(typeof v!=='number'&&/^[\s]*[=+\-@]/.test(s))s="'"+s;return /[\t\n\r"]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s;};
export function copyPayload(rows,columns,withHeaders){const values=rows.map(r=>columns.map(c=>{const v=c.value(r);return c.roundCopy&&typeof v==='number'?Math.round(v):v;}));const labels=columns.map(c=>c.exportLabel||c.label),all=withHeaders?[labels,...values]:values;const text=all.map(row=>row.map(tsv).join('\t')).join('\r\n');const html='<html xmlns:x="urn:schemas-microsoft-com:office:excel"><head><meta charset="utf-8"></head><body><table border="1" cellspacing="0" cellpadding="5" style="border-collapse:collapse;font-family:Malgun Gothic,Arial;font-size:11pt">'+all.map((row,i)=>'<tr>'+row.map(v=>{const numeric=typeof v==='number',tag=withHeaders&&i===0?'th':'td';return `<${tag} ${numeric?'x:num="'+escapeHTML(v)+'"':'x:str="'+escapeHTML(v)+'"'} style="border:1px solid #bac5d1;text-align:${numeric?'right':'left'};mso-number-format:${numeric?'\'#,##0\'':'\'\\@\''}">${escapeHTML(numeric?nf.format(v):v)}</${tag}>`;}).join('')+'</tr>').join('')+'</table></body></html>';return {text,html};}
async function writeClipboard(payload){try{if(navigator.clipboard?.write&&globalThis.ClipboardItem){await navigator.clipboard.write([new ClipboardItem({'text/plain':new Blob([payload.text],{type:'text/plain'}),'text/html':new Blob([payload.html],{type:'text/html'})})]);return true;}throw Error('fallback');}catch{let copied=false;const listener=e=>{e.preventDefault();e.clipboardData.setData('text/plain',payload.text);e.clipboardData.setData('text/html',payload.html);copied=true;};document.addEventListener('copy',listener,{once:true});try{copied=document.execCommand('copy')&&copied;}catch{}document.removeEventListener('copy',listener);if(copied)return true;$('#copyFallback textarea').value=payload.text;$('#copyFallback').showModal();$('#copyFallback textarea').select();return false;}}
async function copyRows(all){if(!state.source)return;const visible=currentRows().filter(r=>!r.manualOnly),rows=all?visible:visible.filter(r=>selectedSet().has(r.id));if(!rows.length){notify('복사할 행의 체크박스를 먼저 선택해 주세요.',true);return;}const success=await writeClipboard(copyPayload(rows,currentColumns(),$('#includeHeaders').checked));if(success)notify(`${nf.format(rows.length)}행을 표로 복사했습니다. Excel·PowerPoint에서 붙여넣으세요.`);}
