async function loadFiles(files,append=false){
 if(!files.length||state.busy)return;busy(true);try{
 if(files.length===1){const raw=await readXlsx(files[0],notify,true);if(I.isIndexSource(raw)){if(append)throw Error('가격지수는 실거래 자료에 추가할 수 없습니다. 가격지수 탭에서 열어 주세요.');busy(false);await loadIndex(files[0],raw);return;}}
 const added=[];for(const file of files)added.push(await readXlsx(file,notify));
 const sources=append&&state.source?[...(state.sources.length?state.sources:[state.source]),...added]:added;
 const merged=E.mergeSources(sources,true),preserve=append&&state.source?{salePolicy:{...state.salePolicy},manualRates:{...state.manualRates},targetDeposit:state.targetDeposit,manual:new Set(state.manual)}:null;
 busy(false);const success=await loadFile({name:merged.name},merged,preserve);if(success){state.sources=sources;notify(sources.length+'개 파일 통합 · 중복 '+merged.duplicates+'건 자동 정리 · '+merged.rows.length+'건 분석.'+(append?' 기존 제외 설정은 유지하고 조회 필터는 전체로 초기화했습니다.':' 같은 파일 안의 동일 사례는 유지합니다.'));}
 }catch(e){notify(e.message,true);}finally{busy(false);$('#export').disabled=indexActive||!state.source;$('#file').value='';$('#additionalFiles').value='';}
}
function refreshPeriods(){if(!state.result)return;const rawRange=E.sourceDateRange(state.source,state.raw),from=state.filters.from||rawRange.from,to=state.filters.to||rawRange.to;const summary=(state.mode==='rent'?R.marketPeriods:E.periodAnalysis)(state.filtered,$('#periodScope').value,$('#periodFrequency').value,from,to,state.filters.lease||'전세');state.result.periods=summary.rows;$('#periodNote').textContent='상단 타입 필터 적용 · 대상·타입별 집계 · '+from+' ~ '+to+' · 거래 없음: - · 날짜 미확인 '+summary.missing+'건 제외'+(state.mode==='rent'?' · '+rentalMetricLabel():'');$('#periodCharts').hidden=true;}
function showPeriodCharts(key,target=false){let rows=state.result.periods.filter(r=>target?r.targetKey===key:r.groupKey===key);if(target){const map=new Map();for(const r of rows){if(!map.has(r.period))map.set(r.period,{...r,count:0,pricedCount:0,sum:0});const g=map.get(r.period);g.count+=r.count;g.pricedCount+=r.pricedCount;g.sum+=(r.priceAverage||0)*r.pricedCount;}rows=[...map.values()].map(r=>({...r,priceAverage:r.pricedCount?r.sum/r.pricedCount:null})).sort((a,b)=>a.period.localeCompare(b.period));}if(!rows.length)return;$('#periodCharts').hidden=false;$('#periodChartTitle').textContent=rows[0].group+' · '+(target?'선택 타입 전체':E.unitValue(rows[0].typeText,'typeText',units));$('#periodPriceTitle').textContent=state.mode==='rent'?rentalMetricLabel()+(state.filters.lease==='월세'?' (만 원/월)':' (만 원)'):'평균 거래금액 (만 원)';drawSimpleChart($('#periodPriceChart'),rows.map(r=>({label:r.period,value:r.priceAverage})),false,$('#periodPriceTitle').textContent,true);drawSimpleChart($('#periodCountChart'),rows.map(r=>({label:r.period,value:r.count||null})),true,'기간별 거래 건수');$('#periodCharts').scrollIntoView({block:'nearest',behavior:'smooth'});}
