function showIndex(on){indexActive=on;$('#addFiles').disabled=on||state.busy;$('#indexPanel').hidden=!on;for(const selector of ['#loadedInfo','#controls','.workspace:not(#indexPanel)','#sourceSection','footer','#multiOptions','#rateNotice']){const node=$(selector);node.hidden=on||(selector==='#loadedInfo'&&!state.source)||(selector==='#rateNotice'&&state.mode!=='rent');}for(const b of $$('.mode-tabs button'))b.setAttribute('aria-selected',b.dataset.mode===(on?'index':state.mode));$('#export').disabled=on||!state.source;}
async function loadIndex(file,prepared=null){if(!file||state.busy)return;busy(true);try{const source=prepared||await readXlsx(file,notify,true);const parsed=I.parseIndex(source);indexData=parsed;$('#indexRegion').replaceChildren();for(const [i,r]of indexData.series.entries()){const o=el('option','',r.region);o.value=i;$('#indexRegion').append(o);}$('#indexBase').replaceChildren();for(const month of indexData.months){const o=el('option','',month);o.value=month;$('#indexBase').append(o);}$('#indexRegion').value='0';$('#indexRegion').disabled=false;$('#indexBase').disabled=false;$('#copyIndex').disabled=false;$('#indexBase').value=indexData.months.find(m=>indexData.series.every(r=>r.values[m]==null||Math.abs(r.values[m]-100)<0.000001)&&indexData.series.some(r=>r.values[m]===100))||indexData.months.at(-1);showIndex(true);renderIndex();notify(indexData.series.length+'개 지역 · '+indexData.months.length+'개월 가격지수를 읽었습니다.');}catch(e){notify(e.message,true);}finally{busy(false);$('#export').disabled=indexActive||!state.source;$('#indexFile').value='';}}
function indexRows(){return indexData?I.rebaseIndex(indexData.series[Number($('#indexRegion').value)],indexData.months,$('#indexBase').value):[];}
function renderIndex(){if(!indexData)return;const rows=indexRows(),body=$('#indexTable tbody');body.replaceChildren();for(const r of rows){const tr=el('tr');for(const v of [r.month,r.original,r.index])tr.append(el('td',typeof v==='number'?'numeric':'',v==null?'—':typeof v==='number'?v.toFixed(2):v));body.append(tr);}const region=indexData.series[Number($('#indexRegion').value)].region;$('#indexOriginalHeading').textContent='원자료 지수'+(indexData.originalBase?' ('+indexData.originalBase+'=100)':'');$('#indexRebasedHeading').textContent='환산 지수 ('+$('#indexBase').value+'=100)';$('#indexNote').textContent=region+' · '+$('#indexBase').value+' = 100 · 원자료 ÷ 기준월 원자료 × 100'+(rows.every(r=>r.index==null)?' · 기준월 값이 없거나 0이어서 환산할 수 없습니다.':'');$('#indexSource').textContent='출처: 업로드 파일 '+indexData.name+' · 원자료 열 사용 · '+indexData.months[0]+' ~ '+indexData.months.at(-1)+' · 표시 소수 둘째 자리, 계산은 원래 정밀도 유지';drawSimpleChart($('#indexChart'),rows.map(r=>({label:r.month,value:r.index})));}
function drawSimpleChart(root,points,bars=false,label=null,connectMissing=false){root.replaceChildren();const valid=points.filter(p=>Number.isFinite(p.value));if(!valid.length){root.append(el('p','hint','해당 기간의 거래 사례가 없습니다. (-)'));return;}const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 1000 220');svg.setAttribute('role','img');svg.setAttribute('aria-label',label||(bars?'기간별 거래 건수':'기준월 환산 가격지수'));const make=(tag,attrs,text)=>{const n=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);if(text!=null)n.textContent=text;svg.append(n);return n;};let lo=bars?0:Math.min(...valid.map(p=>p.value))*.98,hi=Math.max(...valid.map(p=>p.value))*1.02;hi=Math.max(hi,lo+1);if(bars)hi=Math.max(3,Math.ceil(hi/3)*3);const xy=(p,i)=>[65+i*900/Math.max(1,points.length-1),180-(p.value-lo)/(hi-lo)*155];for(let i=0;i<4;i++){const y=25+i*155/3;make('line',{x1:65,x2:965,y1:y,y2:y,class:'chart-grid'});make('text',{x:57,y:y+4,'text-anchor':'end',class:'chart-label'},bars?Math.round(hi-(hi-lo)*i/3):label?nf.format(hi-(hi-lo)*i/3):(hi-(hi-lo)*i/3).toFixed(1));}let segment=[];const flush=()=>{if(segment.length)make('polyline',{points:segment.join(' '),class:'chart-line'});segment=[];};points.forEach((p,i)=>{if(!Number.isFinite(p.value)){if(!connectMissing)flush();if(label)make('text',{x:xy({value:lo},i)[0],y:176,'text-anchor':'middle',class:'chart-label'},'-');return;}const[x,y]=xy(p,i);if(!bars)segment.push(x+','+y);const dot=make(bars?'rect':'circle',bars?{x:x-3,y,width:6,height:180-y,fill:'#0071e3',tabindex:0}:{cx:x,cy:y,r:3,class:'chart-point',tabindex:0});const title=document.createElementNS(ns,'title');title.textContent=p.label+' · '+(bars?p.value+'건':p.value.toFixed(2));dot.append(title);dot.setAttribute('aria-label',title.textContent);});flush();for(const i of [...new Set([0,Math.floor(points.length/2),points.length-1])])make('text',{x:xy({value:lo},i)[0],y:208,'text-anchor':'middle',class:'chart-label'},points[i].label);root.append(svg);}
